import assert from "node:assert/strict";
import { test } from "node:test";
import connect from "connect";
import supertest from "supertest";
import type { IncomingMessage, ServerResponse } from "node:http";
import contentSecurityPolicy from "../middlewares/content-security-policy";

interface ResponseWithLocals extends ServerResponse {
  locals?: Record<string, string>;
}

function getCspNonce(res: ResponseWithLocals): string {
  if (!res.locals || typeof res.locals.cspNonce !== "string") {
    throw new Error("Expected res.locals.cspNonce to be set");
  }
  return res.locals.cspNonce;
}

test("nonce() returns a quoted nonce directive and stores the raw nonce on res.locals", async () => {
  const app = connect()
    .use((req: IncomingMessage, res: ResponseWithLocals, next: () => void) => {
      const nonceFn = contentSecurityPolicy.nonce();
      const directive = nonceFn(req, res);
      res.setHeader("X-Nonce-Directive", directive);
      res.setHeader("X-Raw-Nonce", getCspNonce(res));
      next();
    })
    .use((_req: IncomingMessage, res: ServerResponse) => {
      res.end("ok");
    });

  const response = await supertest(app).get("/").expect(200);

  const directive = response.headers["x-nonce-directive"] as string;
  const rawNonce = response.headers["x-raw-nonce"] as string;

  assert.match(directive, /^'nonce-[A-Za-z0-9_-]+'$/);
  assert.equal(directive, `'nonce-${rawNonce}'`);
});

test("nonce() generates unique nonces for each request", async () => {
  const app = connect()
    .use((req: IncomingMessage, res: ResponseWithLocals, next: () => void) => {
      const nonceFn = contentSecurityPolicy.nonce();
      nonceFn(req, res);
      res.setHeader("X-Raw-Nonce", getCspNonce(res));
      next();
    })
    .use((_req: IncomingMessage, res: ServerResponse) => {
      res.end("ok");
    });

  const response1 = await supertest(app).get("/").expect(200);
  const response2 = await supertest(app).get("/").expect(200);

  const nonce1 = response1.headers["x-raw-nonce"] as string;
  const nonce2 = response2.headers["x-raw-nonce"] as string;

  assert.notEqual(nonce1, nonce2);
  assert.match(nonce1, /^[A-Za-z0-9_-]+$/);
  assert.match(nonce2, /^[A-Za-z0-9_-]+$/);
});

test("nonce() can be used as a CSP directive value", async () => {
  const app = connect()
    .use(
      contentSecurityPolicy({
        directives: {
          "default-src": ["'self'"],
          "script-src": ["'self'", contentSecurityPolicy.nonce()],
        },
      }),
    )
    .use((_req: IncomingMessage, res: ResponseWithLocals) => {
      res.setHeader("X-Raw-Nonce", getCspNonce(res));
      res.end("ok");
    });

  const response = await supertest(app).get("/").expect(200);

  const cspHeader = response.headers["content-security-policy"] as string;
  const rawNonce = response.headers["x-raw-nonce"] as string;

  assert.ok(cspHeader.includes("script-src 'self'"));
  assert.ok(cspHeader.includes(`'nonce-${rawNonce}'`));
});

test("nonce() reuses the same nonce when used in multiple directives in one request", async () => {
  const nonceFn = contentSecurityPolicy.nonce();
  const app = connect()
    .use(
      contentSecurityPolicy({
        directives: {
          "default-src": ["'self'"],
          "script-src": ["'self'", nonceFn],
          "style-src": ["'self'", nonceFn],
        },
      }),
    )
    .use((_req: IncomingMessage, res: ResponseWithLocals) => {
      res.setHeader("X-Raw-Nonce", getCspNonce(res));
      res.end("ok");
    });

  const response = await supertest(app).get("/").expect(200);

  const cspHeader = response.headers["content-security-policy"] as string;
  const rawNonce = response.headers["x-raw-nonce"] as string;
  const nonceSource = `'nonce-${rawNonce}'`;

  assert.equal((cspHeader.match(new RegExp(nonceSource, "g")) || []).length, 2);
  assert.ok(cspHeader.includes(`script-src 'self' ${nonceSource}`));
  assert.ok(cspHeader.includes(`style-src 'self' ${nonceSource}`));
});

